import math

def build_agent(sandbox):
    start_x = 4.5
    start_y = 1.5
    # Create base beam at starting position with higher density for stability
    base_beam = sandbox.add_beam(start_x, start_y, width=0.4, height=1.0, density=5.0)
    segments = []
    pads = []
    joints = []

    # Add four segments within build zone (y <= 5.0)
    for i in range(4):
        y = start_y + i * 1.0
        segment = sandbox.add_beam(start_x, y, width=0.4, height=1.0, density=5.0)
        segments.append(segment)
        # Place pads at right end of each segment within build zone
        pad = sandbox.add_pad(start_x + 0.2, y, radius=0.25, density=1.0)
        pads.append(pad)

        # Connect segments with pivot joints at the top for better leverage
        if i == 0:
            joint = sandbox.add_joint(base_beam, segment, (start_x, y + 0.5), type='pivot', 
                                    lower_limit=-math.pi, upper_limit=math.pi)
        else:
            joint = sandbox.add_joint(segments[i-1], segment, (start_x, y + 0.5), type='pivot', 
                                    lower_limit=-math.pi, upper_limit=math.pi)
        joints.append(joint)

    # Control parameters with increased speed and torque for better climbing
    control = {
        'cycle': 100,
        'overlap': 20,  # Increased overlap to allow longer pad activation
        'p_torso': pads[:2],  # First two pads for initial adhesion
        'p_arm': pads[2:],    # Remaining pads for sequential climbing
        'joints': joints,
        'speed': 5.0,         # Increased motor speed for faster climbing
        'torque': 3.0         # Max torque allowed per joint
    }
    return {'main_body': base_beam, 'control': control}

def agent_action(sandbox, agent_body, step_count):
    c = agent_body.get("control", {})
    if not c:
        return

    cycle = c['cycle']
    phase = step_count % (2 * cycle)
    overlap = c.get('overlap', 20)
    speed = c.get('speed', 5.0)
    torque = c.get('torque', 3.0)
    joints = c.get('joints', [])
    p_torso = c.get('p_torso', [])
    p_arm = c.get('p_arm', [])

    # Sequential pad activation and joint rotation for continuous upward motion
    if phase < cycle:
        # Activate torso pads for initial adhesion
        for p in p_torso:
            sandbox.set_pad_active(p, True)
        # Deactivate arm pads after overlap to focus on base movement
        if phase > overlap:
            for p in p_arm:
                sandbox.set_pad_active(p, False)
        else:
            for p in p_arm:
                sandbox.set_pad_active(p, True)
        # Apply motor to the first joint to initiate climbing
        if joints:
            sandbox.set_motor(joints[0], speed, max_torque=torque)
    else:
        # Activate arm pads for upper segments
        for p in p_arm:
            sandbox.set_pad_active(p, True)
        # Deactivate torso pads after overlap
        if (phase - cycle) > overlap:
            for p in p_torso:
                sandbox.set_pad_active(p, False)
        else:
            for p in p_torso:
                sandbox.set_pad_active(p, True)
        # Sequentially rotate joints for step-by-step climbing
        if joints:
            idx = int((phase - cycle) / overlap)
            if idx < len(joints):
                # Apply consistent motor direction for effective climbing
                sandbox.set_motor(joints[idx], speed, max_torque=torque)
